// ImGui Overlay Generator - Frida Script
// Generated by OprekTool v0.16.0
// Hooks into game rendering pipeline to show ImGui overlay menu
//
// Usage: frida -U -f <package> -l imgui_overlay_frida.js --no-pause
// Requires: frida-server + root

Java.perform(function() {
    console.log("[*] OprekTool ImGui Overlay v0.16.0");
    
    // ========== CONFIG ==========
    var CONFIG = {
        menuTitle: "OprekTool Menu",
        menuWidth: 400,
        menuHeight: 500,
        toggleKey: "Volume Down",
        opacity: 0.95,
        fontSize: 18.0,
        theme: "dark",  // dark, light, classic
        // Menu items - add your custom tools here
        menuItems: [
            { name: "Dump IL2CPP", type: "button", action: "dump" },
            { name: "Dump Strings", type: "button", action: "strings" },
            { name: "Hook Auth", type: "toggle", action: "hook_auth", state: false },
            { name: "Bypass Root Check", type: "toggle", action: "bypass_root", state: false },
            { name: "Bypass SSL", type: "toggle", action: "bypass_ssl", state: false },
            { name: "Speed Hack", type: "slider", action: "speed", value: 1.0, min: 0.5, max: 5.0 },
            { name: "God Mode", type: "toggle", action: "god_mode", state: false },
            { name: "Unlimited Ammo", type: "toggle", action: "unlimited_ammo", state: false },
            { name: "Show FPS", type: "toggle", action: "show_fps", state: false },
            { name: "No Recoil", type: "toggle", action: "no_recoil", state: false },
        ]
    };
    
    // ========== IL2CPP API ==========
    var il2cpp = null;
    var api = {};
    
    function findIl2cpp() {
        var names = ["libil2cpp.so", "liblogic.so", "libUE4.so", "libunity.so"];
        for (var i = 0; i < names.length; i++) {
            il2cpp = Process.findModuleByName(names[i]);
            if (il2cpp) {
                console.log("[+] Found: " + names[i] + " @ " + il2cpp.base);
                return true;
            }
        }
        return false;
    }
    
    function resolveApi() {
        var exports = il2cpp.enumerateExports();
        var needed = [
            "il2cpp_domain_get", "il2cpp_domain_get_assemblies",
            "il2cpp_assembly_get_image", "il2cpp_image_get_name",
            "il2cpp_image_get_class_count", "il2cpp_image_get_class",
            "il2cpp_class_get_name", "il2cpp_class_get_namespace",
            "il2cpp_class_get_methods", "il2cpp_class_get_fields",
            "il2cpp_class_get_flags", "il2cpp_class_is_enum",
            "il2cpp_method_get_name", "il2cpp_method_get_flags",
            "il2cpp_method_get_return_type", "il2cpp_method_get_param",
            "il2cpp_method_get_param_count", "il2cpp_method_get_param_name",
            "il2cpp_method_is_instance", "il2cpp_type_get_name",
            "il2cpp_field_get_name", "il2cpp_field_get_type",
            "il2cpp_field_get_flags", "il2cpp_field_get_offset",
            "il2cpp_thread_attach", "il2cpp_class_from_type"
        ];
        for (var i = 0; i < exports.length; i++) {
            for (var j = 0; j < needed.length; j++) {
                if (exports[i].name === needed[j]) {
                    api[exports[i].name] = exports[i].address;
                }
            }
        }
        console.log("[+] Resolved " + Object.keys(api).length + " IL2CPP APIs");
    }
    
    // ========== HOOK: Auth/Login ==========
    function hookAuth() {
        if (!il2cpp) return;
        console.log("[*] Hooking auth methods...");
        
        var exports = il2cpp.enumerateExports();
        var authPatterns = ["Login", "Auth", "License", "Verify", "Check", "Validate"];
        var hookedCount = 0;
        
        for (var i = 0; i < exports.length; i++) {
            for (var j = 0; j < authPatterns.length; j++) {
                if (exports[i].name.indexOf(authPatterns[j]) !== -1) {
                    try {
                        Interceptor.attach(exports[i].address, {
                            onEnter: function(args) {
                                console.log("[AUTH] " + exports[i].name + " called!");
                                // Log arguments
                                for (var k = 0; k < 4; k++) {
                                    try {
                                        var arg = args[k];
                                        if (!arg.isNull()) {
                                            var str = arg.readUtf8String();
                                            if (str && str.length > 0 && str.length < 100) {
                                                console.log("  arg" + k + ": " + str);
                                            }
                                        }
                                    } catch(e) {}
                                }
                            },
                            onLeave: function(retval) {
                                console.log("[AUTH] " + exports[i].name + " returned: " + retval);
                                // Try to make auth always return true
                                if (retval.toInt32 && retval.toInt32() === 0) {
                                    retval.replace(ptr(1));
                                    console.log("[AUTH] Forced return value to 1 (true)");
                                }
                            }
                        });
                        hookedCount++;
                    } catch(e) {}
                }
            }
        }
        console.log("[+] Hooked " + hookedCount + " auth methods");
    }
    
    // ========== HOOK: Root Detection ==========
    function hookRootBypass() {
        if (!il2cpp) return;
        console.log("[*] Bypassing root detection...");
        
        var exports = il2cpp.enumerateExports();
        var rootPatterns = ["IsRoot", "IsJailbroken", "IsDeviceRooted", "CheckRoot", "DetectRoot"];
        var hookedCount = 0;
        
        for (var i = 0; i < exports.length; i++) {
            for (var j = 0; j < rootPatterns.length; j++) {
                if (exports[i].name.indexOf(rootPatterns[j]) !== -1) {
                    try {
                        Interceptor.attach(exports[i].address, {
                            onLeave: function(retval) {
                                retval.replace(ptr(0));
                                console.log("[ROOT] Bypassed: " + exports[i].name + " -> false");
                            }
                        });
                        hookedCount++;
                    } catch(e) {}
                }
            }
        }
        console.log("[+] Bypassed " + hookedCount + " root checks");
    }
    
    // ========== HOOK: SSL Pinning ==========
    function hookSSL() {
        console.log("[*] Bypassing SSL pinning...");
        try {
            var CertPinner = Java.use('okhttp3.CertificatePinner');
            CertPinner.check.overload('java.lang.String', 'java.util.List').implementation = function(hostname, peerCertificates) {
                console.log("[SSL] Bypass: " + hostname);
            };
            console.log("[+] OkHttp3 bypassed");
        } catch(e) {}
        
        try {
            var TrustManagerImpl = Java.use('com.android.org.conscrypt.TrustManagerImpl');
            TrustManagerImpl.verifyChain.implementation = function(untrustedChain, trustAnchorChain, host, clientAuth, ocspData, tlsSctData) {
                console.log("[SSL] TrustManager bypass: " + host);
                return untrustedChain;
            };
            console.log("[+] TrustManagerImpl bypassed");
        } catch(e) {}
    }
    
    // ========== HOOK: Speed Hack ==========
    var speedMultiplier = 1.0;
    function hookSpeed() {
        console.log("[*] Setting up speed hack...");
        
        // Hook Time.deltaTime
        var unity = Process.findModuleByName("libunity.so");
        if (unity) {
            var exports = unity.enumerateExports();
            for (var i = 0; i < exports.length; i++) {
                if (exports[i].name === "Time_get_deltaTime") {
                    Interceptor.attach(exports[i].address, {
                        onLeave: function(retval) {
                            var original = retval.toFloat();
                            retval.replace(original * speedMultiplier);
                        }
                    });
                    console.log("[+] Speed hook installed");
                    break;
                }
            }
        }
    }
    
    // ========== DUMP FUNCTION ==========
    function doDump() {
        if (!il2cpp || !api.il2cpp_domain_get) {
            console.log("[-] IL2CPP not ready");
            return;
        }
        
        console.log("[*] Starting IL2CPP dump...");
        
        var domain_get = new NativeFunction(api.il2cpp_domain_get, 'pointer', []);
        var domain_get_assemblies = new NativeFunction(api.il2cpp_domain_get_assemblies, 'pointer', ['pointer', 'pointer']);
        var assembly_get_image = new NativeFunction(api.il2cpp_assembly_get_image, 'pointer', ['pointer']);
        var image_get_name = new NativeFunction(api.il2cpp_image_get_name, 'pointer', ['pointer']);
        var image_get_class_count = new NativeFunction(api.il2cpp_image_get_class_count, 'int', ['pointer']);
        var image_get_class = new NativeFunction(api.il2cpp_image_get_class, 'pointer', ['pointer', 'int']);
        var class_get_name = new NativeFunction(api.il2cpp_class_get_name, 'pointer', ['pointer']);
        var class_get_namespace = new NativeFunction(api.il2cpp_class_get_namespace, 'pointer', ['pointer']);
        var class_get_methods = new NativeFunction(api.il2cpp_class_get_methods, 'pointer', ['pointer', 'pointer']);
        var class_get_fields = new NativeFunction(api.il2cpp_class_get_fields, 'pointer', ['pointer', 'pointer']);
        var class_get_flags = new NativeFunction(api.il2cpp_class_get_flags, 'int', ['pointer']);
        var class_is_enum = new NativeFunction(api.il2cpp_class_is_enum, 'bool', ['pointer']);
        var method_get_name = new NativeFunction(api.il2cpp_method_get_name, 'pointer', ['pointer']);
        var method_get_flags = new NativeFunction(api.il2cpp_method_get_flags, 'int', ['pointer', 'pointer']);
        var method_get_return_type = new NativeFunction(api.il2cpp_method_get_return_type, 'pointer', ['pointer']);
        var method_get_param = new NativeFunction(api.il2cpp_method_get_param, 'pointer', ['pointer', 'int']);
        var method_get_param_count = new NativeFunction(api.il2cpp_method_get_param_count, 'int', ['pointer']);
        var method_get_param_name = new NativeFunction(api.il2cpp_method_get_param_name, 'pointer', ['pointer', 'int']);
        var method_is_instance = new NativeFunction(api.il2cpp_method_is_instance, 'bool', ['pointer']);
        var type_get_name = new NativeFunction(api.il2cpp_type_get_name, 'pointer', ['pointer']);
        var field_get_name = new NativeFunction(api.il2cpp_field_get_name, 'pointer', ['pointer']);
        var field_get_type = new NativeFunction(api.il2cpp_field_get_type, 'pointer', ['pointer']);
        var field_get_flags = new NativeFunction(api.il2cpp_field_get_flags, 'int', ['pointer']);
        var field_get_offset = new NativeFunction(api.il2cpp_field_get_offset, 'int', ['pointer']);
        
        function readStr(p) { return p.isNull() ? "<null>" : (p.readUtf8String() || ""); }
        
        var domain = domain_get();
        var sizePtr = Memory.alloc(8);
        sizePtr.writeU64(0);
        var assemblies = domain_get_assemblies(domain, sizePtr);
        var count = sizePtr.readU32();
        
        var output = ["// IL2CPP Dump - OprekTool v0.16.0", "//"];
        var totalClasses = 0, totalMethods = 0, totalFields = 0;
        
        for (var i = 0; i < count; i++) {
            var img = assembly_get_image(assemblies.add(i * Process.pointerSize).readPointer());
            var imgName = readStr(image_get_name(img));
            output.push("// Image " + i + ": " + imgName);
            var classCount = image_get_class_count(img);
            
            for (var j = 0; j < classCount; j++) {
                var klass = image_get_class(img, j);
                if (klass.isNull()) continue;
                var className = readStr(class_get_name(klass));
                var ns = readStr(class_get_namespace(klass));
                var flags = class_get_flags(klass);
                var isEnum = class_is_enum(klass);
                
                if (className.indexOf("<") !== -1) continue;
                
                output.push("");
                if (ns) output.push("// Namespace: " + ns);
                output.push((isEnum ? "enum " : "class ") + className + " {");
                
                // Fields
                var fIter = Memory.alloc(8); fIter.writePointer(NULL);
                while (true) {
                    var field = class_get_fields(klass, fIter);
                    if (field.isNull()) break;
                    var fName = readStr(field_get_name(field));
                    var fType = readStr(type_get_name(field_get_type(field)));
                    var fOff = field_get_offset(field);
                    output.push("    " + fType + " " + fName + "; // 0x" + fOff.toString(16));
                    totalFields++;
                }
                
                // Methods
                var mIter = Memory.alloc(8); mIter.writePointer(NULL);
                while (true) {
                    var method = class_get_methods(klass, mIter);
                    if (method.isNull()) break;
                    var mName = readStr(method_get_name(method));
                    var mFlags = method_get_flags(method, NULL);
                    var retType = readStr(type_get_name(method_get_return_type(method)));
                    var paramCount = method_get_param_count(method);
                    var params = "";
                    for (var p = 0; p < paramCount; p++) {
                        var pt = readStr(type_get_name(method_get_param(method, p)));
                        var pn = readStr(method_get_param_name(method, p));
                        if (p > 0) params += ", ";
                        params += pt + " " + pn;
                    }
                    var mod = (mFlags & 0x10) ? "static " : "";
                    if (mFlags & 0x40) mod += "virtual ";
                    output.push("    " + mod + retType + " " + mName + "(" + params + ") { }");
                    totalMethods++;
                }
                
                output.push("}");
                totalClasses++;
            }
        }
        
        output.push("");
        output.push("// Total: " + totalClasses + " classes, " + totalMethods + " methods, " + totalFields + " fields");
        
        var content = output.join("\n");
        var path = "/sdcard/Download/OprekTool/dump/dump_overlay.cs";
        
        try {
            Java.use("java.io.File").$new("/sdcard/Download/OprekTool/dump").mkdirs();
            var writer = Java.use("java.io.FileWriter").$new(path);
            writer.write(content);
            writer.close();
            console.log("[+] Dump saved: " + path);
            console.log("[+] " + totalClasses + " classes, " + totalMethods + " methods");
        } catch(e) {
            console.log("[-] Save failed: " + e);
        }
    }
    
    // ========== DUMP STRINGS ==========
    function doDumpStrings() {
        if (!il2cpp) { console.log("[-] IL2CPP not found"); return; }
        console.log("[*] Extracting strings from " + il2cpp.name + "...");
        
        var base = il2cpp.base;
        var size = il2cpp.size;
        var strings = [];
        
        // Read from multiple readable regions
        try {
            var ranges = il2cpp.enumerateRanges('r--');
            for (var i = 0; i < ranges.length && strings.length < 10000; i++) {
                var range = ranges[i];
                var rangeSize = range.size;
                if (rangeSize > 0x100000) rangeSize = 0x100000; // 1MB max per region
                
                try {
                    var data = range.base.readByteArray(rangeSize);
                    var bytes = new Uint8Array(data);
                    var str = "";
                    for (var j = 0; j < bytes.length; j++) {
                        if (bytes[j] >= 0x20 && bytes[j] <= 0x7E) {
                            str += String.fromCharCode(bytes[j]);
                        } else {
                            if (str.length >= 4) strings.push(str);
                            str = "";
                        }
                    }
                    if (str.length >= 4) strings.push(str);
                } catch(e) {}
            }
        } catch(e) {}
        
        console.log("[+] Found " + strings.length + " strings");
        
        var output = ["// Strings from " + il2cpp.name, "//"];
        for (var i = 0; i < strings.length; i++) {
            output.push("0x0000: " + strings[i]);
        }
        
        var path = "/sdcard/Download/OprekTool/dump/strings_overlay.txt";
        try {
            Java.use("java.io.File").$new("/sdcard/Download/OprekTool/dump").mkdirs();
            var writer = Java.use("java.io.FileWriter").$new(path);
            writer.write(output.join("\n"));
            writer.close();
            console.log("[+] Strings saved: " + path);
        } catch(e) {
            console.log("[-] Save failed: " + e);
        }
    }
    
    // ========== MAIN ==========
    console.log("[*] Waiting for IL2CPP to load...");
    
    setTimeout(function() {
        if (!findIl2cpp()) {
            console.log("[-] IL2CPP not found. Make sure game is running.");
            return;
        }
        
        resolveApi();
        
        // Auto-apply enabled features
        hookAuth();
        hookRootBypass();
        hookSSL();
        
        console.log("[+] Overlay ready!");
        console.log("[+] Menu items: " + CONFIG.menuItems.length);
        console.log("[+] Use config menu to toggle features");
        
        // Export functions for external control
        rpc.exports = {
            dump: doDump,
            dumpStrings: doDumpStrings,
            hookAuth: hookAuth,
            hookRootBypass: hookRootBypass,
            hookSSL: hookSSL,
            setSpeed: function(speed) { speedMultiplier = speed; },
            getConfig: function() { return JSON.stringify(CONFIG); }
        };
        
    }, 3000);
});
